  const deg = r => r * 180 / Math.PI, rad = d => d * Math.PI / 180;

  /* ---------- functions: transformations, special functions ---------- */
  const BASE = { sq: [x => x * x, 'x²', 'all reals', 'y ≥ 0'], abs: [x => Math.abs(x), '|x|', 'all reals', 'y ≥ 0'], sqrt: [x => (x >= 0 ? Math.sqrt(x) : NaN), '√x', 'x ≥ 0', 'y ≥ 0'], cube: [x => x * x * x, 'x³', 'all reals', 'all reals'], recip: [x => (Math.abs(x) < 1e-9 ? NaN : 1 / x), '1/x', 'x ≠ 0', 'y ≠ 0'], exp: [x => Math.exp(x), 'eˣ', 'all reals', 'y > 0'], ln: [x => (x > 0 ? Math.log(x) : NaN), 'ln x', 'x > 0', 'all reals'], sin: [Math.sin, 'sin x', 'all reals', '−1 ≤ y ≤ 1'], floor: [x => Math.floor(x), '⌊x⌋ (greatest integer)', 'all reals', 'integers'], frac: [x => x - Math.floor(x), '{x} (fractional part)', 'all reals', '0 ≤ y < 1'], sgn: [x => Math.sign(x), 'sgn x (signum)', 'all reals', '{−1, 0, 1}'] };
