    sel: [['base', T('base function f(x)', 'الدالة الأساسية'), [['sq', 'x²', /x\s*\^?\s*2|square|quadratic/i], ['abs', '|x|', /modulus|absolute/i], ['sqrt', '√x', /square root|√/i], ['cube', 'x³', /cube|x\s*\^?\s*3/i], ['recip', '1/x', /reciprocal|1\/x/i], ['exp', 'eˣ', /exponential|e\^x/i], ['ln', 'ln x', /\bln\b|log/i], ['sin', 'sin x', /\bsin/i], ['floor', '⌊x⌋', /greatest integer|floor/i], ['frac', '{x}', /fractional/i], ['sgn', 'sgn x', /signum|sgn/i]], 'sq']],
