    sel: [['op', T('show', 'اعرض'), [['z', 'z, z̄, |z|, arg z'], ['mul', 'z · w (rotate and scale)', /multipl|product|z\s*\*?\s*w|rotat/i], ['div', 'z / w', /divi|quotient/i], ['pow', 'zⁿ (De Moivre)', /de ?moivre|power|\^\s*\d/i], ['roots', T('n-th roots of unity', 'جذور الواحد'), /roots of unity/i]], 'z']],
    p: [['a', 'Re z', '', -6, 6, 0.1, 3], ['b', 'Im z', '', -6, 6, 0.1, 4], ['c', 'Re w', '', -4, 4, 0.1, 0], ['d', 'Im w', '', -4, 4, 0.1, 1], ['n', 'n', '', 2, 12, 1, 3, /\b(\d+)(?:th|rd|nd|st)? roots of unity|cube roots/i]],
    parse: t => { const m = String(t).replace(/\s+/g, '').match(/z=(-?\d+(?:\.\d+)?)([+-]\d*(?:\.\d+)?)i/i); const o = m ? { a: +m[1], b: m[2] === '+' ? 1 : m[2] === '-' ? -1 : +m[2] } : {}; if (/cube roots of unity/i.test(t)) o.n = 3; return o; },
    equal: true, auto: true, view: S => { const r = Math.max(2, Math.hypot(S.a, S.b), S.op === 'pow' ? Math.min(60, Math.hypot(S.a, S.b) ** S.n) : 0, S.op === 'mul' ? Math.hypot(S.a, S.b) * Math.hypot(S.c, S.d) : 0) * 1.25; return { x0: -r, x1: r, y0: -r, y1: r }; }, labels: { x: 'Re', y: 'Im' },
