    sel: [['c', T('curve', 'المنحنى'), [['cardioid', T('cardioid', 'قلبي'), /cardioid|1\s*\+\s*cos/i], ['rose', T('rose', 'وردي'), /rose/i], ['limacon', T('limaçon', 'ليماسون'), /lima/i], ['spiral', T('spiral', 'حلزوني'), /spiral/i], ['lemn', T('lemniscate', 'لمنسكات'), /lemniscate/i]], 'cardioid']],
