    equal: true, auto: true, view: S => { const r = (S.c === 'limacon' ? S.a + S.b : S.c === 'spiral' ? S.a * 2 * Math.PI : 2 * S.a) * 1.15 + 0.2; return { x0: -r, x1: r, y0: -r, y1: r }; },
    draw(p, S, c, H) { const f = PC[S.c][1], end = Math.min(rad(S.th), PC[S.c][2] + (S.c === 'spiral' ? 0 : 0)); const pts = []; for (let i = 0; i <= 900; i++) { const t = end * i / 900, r = f(t, S); pts.push(isFinite(r) ? [r * Math.cos(t), r * Math.sin(t)] : null); } p.path(pts, c.pal[0], { w: 2.6 });
      const r = f(end, S); if (isFinite(r)) { p.path([[0, 0], [r * Math.cos(end), r * Math.sin(end)]], c.pal[3], { w: 1.4 }); p.dot(r * Math.cos(end), r * Math.sin(end), c.pal[3], `r = ${f3(r)}`); } },
    ro: S => { const area = polarArea(S); return [[T('curve', 'المنحنى'), PC[S.c][0]], [T('enclosed area ½∫r² dθ', 'المساحة'), area != null ? f3(area) : '—'], ...(S.c === 'rose' ? [[T('petals', 'البتلات'), String(S.k % 2 ? S.k : 2 * S.k)]] : [])]; },
