    sel: [['curve', T('curve', 'المنحنى'), [['cycloid', T('cycloid', 'سيكلويد'), /cycloid|rolling/i], ['lissajous', 'Lissajous', /lissajous/i], ['ellipse', T('ellipse', 'قطع ناقص'), /ellipse/i]], 'cycloid']],
    p: [['r', T('wheel radius r', 'نصف قطر العجلة'), '', 0.5, 3, 0.1, 1], ['fa', T('x frequency', 'تردد x'), '', 1, 7, 1, 3], ['fb', T('y frequency', 'تردد y'), '', 1, 7, 1, 2], ['delta', T('phase δ', 'الطور'), '°', 0, 180, 1, 90], ['t0', T('parameter t', 'الوسيط t'), 'rad', 0, 12.56, 0.01, 1.5]], tog: [['play', T('Animate t', 'حرّك t'), true]],
    equal: true, auto: true, view: S => (S.curve === 'cycloid' ? { x0: -0.5, x1: 4 * Math.PI * S.r + 0.5, y0: -0.5, y1: 2 * S.r + 1.5 } : S.curve === 'lissajous' ? { x0: -1.4, x1: 1.4, y0: -1.4, y1: 1.4 } : { x0: -4, x1: 4, y0: -3, y1: 3 }),
    draw(p, S, c, H) { const C0 = PM[S.curve], T1 = S.curve === 'cycloid' ? 4 * Math.PI : 2 * Math.PI; H.param(p, t => C0[1](t, S), t => C0[2](t, S), 0, T1, c.pal[0], { w: 2.4 }, 800);
      const t = S.t0 % T1, x = C0[1](t, S), y = C0[2](t, S); if (S.curve === 'cycloid') { H.circle(p, S.r * t, S.r, S.r, c.muted, { w: 1.4 }); p.path([[S.r * t, S.r], [x, y]], c.muted, { w: 1.2 }); p.path([[p.view.x0, 0], [p.view.x1, 0]], c.ink, { w: 1.4 }); }
      p.dot(x, y, c.pal[3], 'P'); const dx = C0[3](t, S), dy = C0[4](t, S), n = Math.hypot(dx, dy) || 1, s = (p.view.x1 - p.view.x0) * 0.12; p.path([[x - dx / n * s, y - dy / n * s], [x + dx / n * s, y + dy / n * s]], c.pal[1], { w: 1.8 }); },
    ro: S => { const C0 = PM[S.curve], t = S.t0 % (S.curve === 'cycloid' ? 4 * Math.PI : 2 * Math.PI), dx = C0[3](t, S), dy = C0[4](t, S); return [['t', f3(t)], ['(x, y)', `(${f3(C0[1](t, S))}, ${f3(C0[2](t, S))})`], ['dy/dx = (dy/dt)/(dx/dt)', Math.abs(dx) < 1e-9 ? T('vertical tangent', 'مماس رأسي') : f3(dy / dx)]]; },
    st: S => { const C0 = PM[S.curve], t = S.t0, dx = C0[3](t, S), dy = C0[4](t, S); return { x: C0[1](t, S), y: C0[2](t, S), slope: Math.abs(dx) < 1e-12 ? null : dy / dx }; },
    intro: S => (S.curve === 'cycloid' ? T('A point on the rim of a wheel rolling without slipping traces a cycloid: x = r(t − sin t), y = r(1 − cos t). Its tangent (blue) is found from dy/dx = (dy/dt)/(dx/dt) = sin t/(1 − cos t) = cot(t/2); it is vertical at the cusps where the point touches the ground.', 'السيكلويد.') : T('Both x and y depend on the parameter t; the curve is the path of (x(t), y(t)). Its slope is dy/dx = (dy/dt)/(dx/dt).', 'منحنى وسيطي.')),
